const form = $input.first().json;
const qp = form.formQueryParameters || {};
const instance = (qp.instancia || qp.instance || '').trim();
const remoteJid = (qp.whatsapp || qp.remoteJid || '').trim();

const serie = (form['Série / Turma'] || '').trim();
const disciplina = (form['Disciplina'] || '').trim();
const tema = (form['Tema da atividade'] || '').trim();
const descricao = (form['Descrição / contexto extra'] || '').trim();
const ilustracao = (form['Ilustração preferida'] || '').trim();
const numQ = (form['Número de questões'] || '6 questões (padrão)').trim();
const tipoQ = (form['Tipo de questões'] || 'Mista (recomendado)').trim();
const modoA = (form['Modo de acessibilidade'] || 'Padrão — turma regular').trim();

const num = parseInt(numQ) || 6;
const modo_acessivel = modoA.indexOf('Padrão') === 0 ? false : true;
const nivel_acessivel = modoA.indexOf('Completo') === 0 ? 'completo' : (modoA.indexOf('Leve') === 0 ? 'leve' : 'nenhum');

if (!serie || !disciplina || !tema) {
  throw new Error('Campos obrigatórios faltando: série, disciplina ou tema.');
}

return [{ json: { instance, remoteJid, serie, disciplina, tema, descricao, ilustracao, num_questoes: num, tipo_questoes: tipoQ, modo_acessivel, nivel_acessivel } }];

const ctx = $('📦 Mapear Form → Payload').first().json;
const resp = $input.first().json;
const content = resp.choices?.[0]?.message?.content || '{}';
let atv;
try { atv = JSON.parse(content); }
catch(e) {
  const m = content.match(/\{[\s\S]*\}/);
  atv = m ? JSON.parse(m[0]) : { detectado: false };
}

if (atv && atv.niveis) {
  atv.niveis.forEach(n => (n.questoes||[]).forEach(q => {
    if (q.alternativas && Array.isArray(q.alternativas)) {
      q.alternativas = q.alternativas.map(a => typeof a === 'string' ? a : (a.texto||a.text||a.label||a.opcao||Object.values(a)[0]||'')).filter(x => String(x).trim() !== '');
    }
    if (q.linha_resposta && typeof q.linha_resposta !== 'string') q.linha_resposta = String(q.linha_resposta);
    if (q.linhas_resposta !== undefined) q.linhas_resposta = parseInt(q.linhas_resposta)||0;
  }));
}

atv.instance = ctx.instance;
atv.remoteJid = ctx.remoteJid;
if (atv.modo_acessivel === undefined) atv.modo_acessivel = ctx.modo_acessivel;
if (atv.detectado === undefined) atv.detectado = true;

return [{ json: atv }];

